using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchNotes>();
builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the given topic. " +
    "Use the add_note tool to save key findings as you research. " +
    "Search multiple aspects of the topic, take notes on important findings, " +
    "then provide a final comprehensive summary.");

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 60));

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic thoroughly, searching for multiple aspects, " +
        $"take notes on key findings, and then provide a summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools =
        [
            AIFunctionFactory.Create(researchTools.WebSearch),
            AIFunctionFactory.Create(researchTools.AddNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine($"\n{new string('-', 60)}");
var notes = host.Services.GetRequiredService<ResearchNotes>();
Console.WriteLine($"\n📝 Notes collected ({notes.Notes.Count}):");
foreach (var note in notes.Notes)
{
    Console.WriteLine($"  • {note}");
}

// --- Supporting types ---

public class ResearchNotes
{
    public List<string> Notes { get; } = [];
}

public class ResearchTools(ResearchNotes notes)
{
    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public string WebSearch([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing Search, Google Custom Search, etc.) in production.
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        var results = SimulateSearchResults(query);
        return JsonSerializer.Serialize(new { query, results });
    }

    [Description("Save a research note capturing a key finding.")]
    public string AddNote([Description("The note text to save")] string note)
    {
        notes.Notes.Add(note);
        Console.WriteLine($"  📌 Note saved: \"{note[..Math.Min(note.Length, 80)]}...\"");
        return $"Note saved successfully. Total notes: {notes.Notes.Count}";
    }

    [Description("Retrieve all notes collected so far.")]
    public string GetNotes()
    {
        if (notes.Notes.Count == 0)
            return "No notes collected yet.";

        return JsonSerializer.Serialize(notes.Notes);
    }

    private static List<SearchResult> SimulateSearchResults(string query)
    {
        var queryLower = query.ToLowerInvariant();
        var results = new List<SearchResult>();

        if (queryLower.Contains("history") || queryLower.Contains("origin"))
        {
            results.Add(new("Historical Overview", "https://example.com/history",
                $"The topic '{query}' has roots dating back several decades. Key milestones include " +
                "early research in the 1960s, significant breakthroughs in the 1990s, and modern " +
                "developments that have accelerated progress since 2010."));
        }

        if (queryLower.Contains("application") || queryLower.Contains("use"))
        {
            results.Add(new("Practical Applications", "https://example.com/applications",
                $"'{query}' is widely applied in healthcare, finance, transportation, and education. " +
                "Recent innovations have enabled real-time processing and edge deployment."));
        }

        if (queryLower.Contains("future") || queryLower.Contains("trend"))
        {
            results.Add(new("Future Trends", "https://example.com/trends",
                $"Experts predict '{query}' will see significant growth. Key trends include " +
                "increased automation, ethical frameworks, and cross-domain integration."));
        }

        // Default results for any query
        if (results.Count == 0)
        {
            results.Add(new("Overview", $"https://example.com/{Uri.EscapeDataString(query)}",
                $"'{query}' is a significant area of study and development. It encompasses multiple " +
                "sub-fields and has attracted substantial investment from both public and private sectors."));
            results.Add(new("Recent Developments", $"https://example.com/{Uri.EscapeDataString(query)}/recent",
                $"Recent advances in '{query}' include improved algorithms, larger datasets, " +
                "and more efficient hardware. Several major companies have announced new initiatives."));
            results.Add(new("Challenges", $"https://example.com/{Uri.EscapeDataString(query)}/challenges",
                $"Key challenges in '{query}' include scalability, interpretability, data quality, " +
                "and ensuring equitable access to the technology."));
        }

        return results;
    }
}

public record SearchResult(string Title, string Url, string Snippet);

