arguments.new_str:
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<ResearchNotes>();
builder.Services.AddSingleton<ResearchTools>();

builder.Services.AddChatClient(services =>
    new OpenAIClient(apiKey)
        .GetChatClient(modelId)
        .AsIChatClient());

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.WebSearch),
    AIFunctionFactory.Create(researchTools.AddNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "You are a research assistant. Use the web_search tool to find information about the given topic. " +
        "Use the add_note tool to save key findings as you research. " +
        "Search multiple aspects of the topic, take notes on important findings, " +
        "then provide a final comprehensive summary.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
    },
});

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 60));

var session = await agent.CreateSessionAsync();

var prompt = $"Research the following topic thoroughly. Use the web_search tool to find information " +
    $"about different aspects of the topic. Use the add_note tool to save key findings. " +
    $"After researching, provide a comprehensive summary.\n\nTopic: {topic}";

var result = await agent.RunAsync(prompt, session);

foreach (var message in result.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine($"\n{new string('-', 60)}");
var notes = host.Services.GetRequiredService<ResearchNotes>();
Console.WriteLine($"\n📝 Notes collected ({notes.Notes.Count}):");
foreach (var note in notes.Notes)
{
    Console.WriteLine($"  • {note}");
}

